@startuml
class RepairShop {
  +name : string
  +address : string
  +numberOfEmployees : int
}

class Employee {
  +taxCode : string
  +address : string
  +phoneNumber : string
  +yearsOfService : int
}

class Director {
  +taxCode : string
  +address : string
  +phoneNumber : string
  +age : int
}

class Repair {
  +code : string
  +checkInTime : datetime
  +checkInDate : date
  +returnTime : datetime
  +returnDate : date
}

class Vehicle {
  +model : string
  +type : string
  +licensePlate : string
  +yearOfRegistration : int
}

class Owner {
  +taxCode : string
  +address : string
  +phoneNumber : string
}

class ChainManager {
}

class AccountingOffice {
}

RepairShop "1" *-- "1..*" Employee : has
RepairShop "1" -- "1" Director : has director
RepairShop "1" -- "*" Repair : performs
Vehicle "1" -- "*" Repair : undergoes
Vehicle "1" -- "1" Owner : owned by
Employee <|-- Director

ChainManager ..> RepairShop : analyzes
ChainManager ..> Employee : analyzes
ChainManager ..> Repair : analyzes
Director ..> AccountingOffice : communicates results
Owner ..> Vehicle : owns
@enduml

